-- Prediction Query
SELECT C.name AS country_name, AVG(P.weight) AS average_weight FROM Player AS P INNER JOIN Team AS T ON P.player_api_id = T.team_api_id INNER JOIN Country AS C ON T.team_fifa_api_id = C.id GROUP BY C.id, C.name ORDER BY average_weight DESC, country_name NULLS LAST LIMIT 1;

